namespace QuicNet.Geolocation;

/// <summary>Multi-branch search: exploration stays global; refinement never commits irrevocably to one country.</summary>
public static class HierarchicalLocationPlanner
{
    public static HierarchyAssessment Assess(Catalog catalog, MeasurementSession session, LocationUpdate update,
        FingerprintAssessment fingerprints)
    {
        var hypotheses = new List<GeographicHypothesis>();
        var known = catalog.Landmarks.ToDictionary(a => a.Id, StringComparer.Ordinal);
        var measured = session.Observations.Where(o => o.MinimumRttMs.HasValue && known.ContainsKey(o.LandmarkId))
            .OrderBy(o => o.MinimumRttMs).DistinctBy(o => known[o.LandmarkId].SiteId ?? o.LandmarkId).ToArray();
        if (fingerprints.Matches.Count > 0)
        {
            foreach (var group in fingerprints.Matches.GroupBy(p => p.CountryCode).OrderByDescending(g => g.Sum(p => p.RelativeScore)).Take(4))
            {
                var best = group.MaxBy(p => p.RelativeScore)!;
                hypotheses.Add(new("country:" + group.Key, "country", group.Key, group.Key, best.Position,
                    group.Sum(p => p.RelativeScore), 1000, best.MatchedSites, "empirical-relative-pattern"));
            }
            foreach (var group in fingerprints.Matches.GroupBy(p => (p.CountryCode, p.Region, p.Locality)).OrderByDescending(g => g.Sum(p => p.RelativeScore)).Take(8))
            {
                var best = group.MaxBy(p => p.RelativeScore)!;
                double spread = group.Max(p => Geography.DistanceKm(best.Position, p.Position) + p.UncertaintyKm);
                hypotheses.Add(new("profile:" + best.ProfileId, "local-area", string.Join(" · ", new[] { best.Locality, best.Region }.Where(s => !string.IsNullOrWhiteSpace(s))),
                    best.CountryCode, best.Position, group.Sum(p => p.RelativeScore), Math.Max(25, spread), best.MatchedSites, "empirical-relative-pattern"));
            }
        }
        else if (measured.Length > 0)
        {
            // Fastest-three per country avoids giving a dense country a vote for every colocated anchor.
            var groups = measured.Where(o => !string.IsNullOrWhiteSpace(known[o.LandmarkId].CountryCode))
                .GroupBy(o => known[o.LandmarkId].CountryCode!).Select(g =>
                {
                    var first = g.Take(3).ToArray(); var best = known[first[0].LandmarkId];
                    double representative = RobustStatistics.Median(first.Select(o => o.MinimumRttMs!.Value));
                    return (Country: g.Key, Best: best, Latency: representative, Count: g.Count());
                }).OrderBy(x => x.Latency).Take(5).ToArray();
            double baseline = groups.Length > 0 ? groups[0].Latency : 0;
            var weights = groups.Select(g => Math.Exp(-Math.Min(50, (g.Latency - baseline) / Math.Max(3, baseline * .4)))).ToArray();
            double total = weights.Sum();
            for (int i = 0; i < groups.Length; i++)
            {
                var g = groups[i];
                hypotheses.Add(new("country:" + g.Country, "country", g.Country, g.Country, g.Best.Position,
                    weights[i] / total, 1200, g.Count, "routing-affinity-not-country-proof"));
            }
        }
        var fit = update.Localities?.Fit;
        if (fit is not null && fingerprints.Matches.Count == 0)
        {
            var nearby = LocalityCatalog.Default.Near(fit.Position, 8, Math.Max(50, Math.Min(500, fit.ModelSpreadKm)));
            // The geographic fit only guides probing. It is deliberately not assigned confidence.
            foreach (var countryGroup in nearby.GroupBy(n => n.Place.CountryCode).Take(3))
            {
                var first = countryGroup.First();
                hypotheses.Add(new("fit:" + countryGroup.Key, "regional-area", first.Place.Region, countryGroup.Key,
                    fit.Position, .5, Math.Max(50, fit.ModelSpreadKm), fit.IndependentSites, "uncalibrated-network-model"));
            }
        }
        var focus = hypotheses.Where(h => h.Level != "country").OrderByDescending(h => h.RelativeScore).Take(4).ToArray();
        var places = focus.SelectMany(h => LocalityCatalog.Default.Near(h.Position, 6, Math.Min(500, h.SearchRadiusKm), h.CountryCode))
            .Select(p => p.Place).DistinctBy(p => p.Id).Take(24).ToArray();
        string stage = measured.Length == 0 ? "world-exploration" : focus.Length > 0 ?
            fingerprints.Matches.Count > 0 ? "local-area-candidates" : "regional-candidates" : "country-candidates";
        return new(stage, hypotheses.ToArray(), places,
            "Alternatives remain open. These are search hypotheses, not confirmed borders, municipality identifications or calibrated probabilities. Nearby place names do not imply a probe exists there.");
    }

    public static List<Landmark> Next(Catalog catalog, MeasurementSession session, LocationUpdate update,
        int count, int round, FingerprintDatabase? profiles = null, uint? asn = null)
    {
        var eligible = catalog.Landmarks.Where(a => a.Kind == "anchor" && a.ProbeEligible)
            .OrderBy(a => a.Id, StringComparer.Ordinal).ToArray();
        var seen = session.Observations.Select(o => o.LandmarkId).ToHashSet(StringComparer.Ordinal);
        var observedSites = eligible.Where(a => seen.Contains(a.Id)).Select(a => a.SiteId ?? a.Id).ToHashSet(StringComparer.Ordinal);
        var fresh = eligible.Where(a => !seen.Contains(a.Id) && !observedSites.Contains(a.SiteId ?? a.Id)).ToArray();
        var result = new List<Landmark>(); var sites = new HashSet<string>(StringComparer.Ordinal);
        var hypotheses = update.Enhanced?.Hierarchy.Hypotheses ?? [];
        var referencePositions = eligible.Where(a => seen.Contains(a.Id)).Select(a => a.Position).ToList();
        void Add(Landmark a) { if (result.Count < count && sites.Add(a.SiteId ?? a.Id)) result.Add(a); }
        // Farthest-first global coverage is independent of the current "winning" country.
        int exploration = round == 0 ? count : Math.Max(2, count / 4);
        for (int i = 0; i < exploration; i++)
        {
            var candidates = fresh.Where(a => !sites.Contains(a.SiteId ?? a.Id)).ToArray();
            if (candidates.Length == 0) break;
            Landmark pick = referencePositions.Count == 0
                ? candidates.OrderBy(a => a.CountryCode == "ES" ? 0 : 1).ThenBy(a => a.Id, StringComparer.Ordinal).First()
                : candidates.MaxBy(a => referencePositions.Min(p => Geography.DistanceKm(p, a.Position)))!;
            Add(pick); referencePositions.Add(pick.Position);
        }
        // Empirical profile variance is preferred; geometry is only a fallback scheduling proxy.
        double Information(Landmark anchor)
        {
            var empirical = profiles?.Profiles.Where(p => p.AddressFamily == session.AddressFamily && p.GroundTruthConsented &&
                (!asn.HasValue || !p.Asn.HasValue || p.Asn == asn))
                .Select(p => p.Features.FirstOrDefault(f => f.SiteId == (anchor.SiteId ?? anchor.Id)))
                .Where(f => f is not null).Take(128).Select(f => f!).ToArray() ?? [];
            if (empirical.Length >= 3)
            {
                double mean = empirical.Average(f => f.MinimumMs);
                return empirical.Average(f => Math.Pow(f.MinimumMs - mean, 2)) / (1 + empirical.Average(f => f.MadMs * f.MadMs));
            }
            var predictions = hypotheses.Select(h => Geography.DistanceKm(h.Position, anchor.Position) / 100).ToArray();
            double discrimination = predictions.Length < 2 ? 0 : predictions.Max() - predictions.Min();
            double local = hypotheses.Count == 0 ? 0 : hypotheses.Max(h => h.RelativeScore / (1 + Geography.DistanceKm(h.Position, anchor.Position) / Math.Max(50, h.SearchRadiusKm)));
            double same = asn.HasValue && anchor.Asn == asn ? .2 : 0;
            return discrimination + 10 * local + same;
        }
        // Keep one targeted slot for each leading branch before spending remaining slots on information gain.
        foreach (var h in hypotheses.OrderByDescending(h => h.RelativeScore).Take(3))
        {
            var pick = fresh.Where(a => !sites.Contains(a.SiteId ?? a.Id)).MinBy(a => Geography.DistanceKm(h.Position, a.Position));
            if (pick is not null) Add(pick);
        }
        foreach (var a in fresh.OrderByDescending(Information))
        {
            if (result.Count >= Math.Max(exploration, count - 2)) break;
            if (a.Asn.HasValue && result.Count(x => x.Asn == a.Asn) >= Math.Max(2, count / 3)) continue;
            Add(a);
        }
        // Reuse the existing information planner instead of maintaining a disconnected second path.
        if (result.Count < count && eligible.Length > 0)
        {
            var hints = InformationLandmarkPlanner.Next(catalog, session, update, Math.Clamp(count, 6, 64), round + 1, regional: true);
            foreach (var a in hints) Add(a);
        }
        // Repeat discriminating / low latency destinations when fresh measurements are exhausted.
        var byId = eligible.ToDictionary(a => a.Id, StringComparer.Ordinal);
        foreach (var o in session.Observations.Where(o => byId.ContainsKey(o.LandmarkId)).OrderBy(o => o.MinimumRttMs ?? double.MaxValue)) Add(byId[o.LandmarkId]);
        foreach (var a in fresh) Add(a);
        return result;
    }
}

namespace QuicNet.Geolocation;

/// <summary>Robust nearest-profile matching. Scores express similarity, never geographic confidence.</summary>
public static class NetworkFingerprintEstimator
{
    public const string FeatureVersion = "common-sites-relative-rtt-v1";
    public static IReadOnlyDictionary<string, FingerprintFeature> Extract(Catalog catalog, MeasurementSession session)
    {
        var index = catalog.Landmarks.ToDictionary(a => a.Id, StringComparer.Ordinal);
        return session.Observations.Where(o => index.ContainsKey(o.LandmarkId))
            .GroupBy(o => index[o.LandmarkId].SiteId ?? o.LandmarkId, StringComparer.Ordinal)
            .Select(g => (Site: g.Key, Stats: RobustStatistics.Summarize(g.SelectMany(o => o.Samples)
                .Where(s => s.TimingMethod == "elapsed-upper-v1"))))
            .Where(x => x.Stats.Successes >= 2)
            .ToDictionary(x => x.Site, x => new FingerprintFeature(x.Site, x.Stats.MinimumMs!.Value,
                x.Stats.MedianMs!.Value, x.Stats.MadMs!.Value, x.Stats.Successes), StringComparer.Ordinal);
    }

    public static void Validate(FingerprintDatabase database)
    {
        ArgumentNullException.ThrowIfNull(database);
        if (database.SchemaVersion != 1 || database.FeatureVersion != FeatureVersion || database.Profiles is null || database.Profiles.Count > 50000)
            throw new InvalidDataException("Unsupported fingerprint database or excessive profile count.");
        var ids = new HashSet<string>(StringComparer.Ordinal);
        foreach (var p in database.Profiles)
        {
            p.Position.Validate();
            if (string.IsNullOrWhiteSpace(p.Id) || !ids.Add(p.Id) || p.Features is null || p.Features.Count is < 4 or > 20000 ||
                p.AddressFamily is not ("ipv4" or "ipv6") || p.Protocol != "icmp" || p.TimingMethod != "elapsed-upper-v1" ||
                !p.GroundTruthConsented || !double.IsFinite(p.GroundTruthUncertaintyKm) || p.GroundTruthUncertaintyKm is < 0 or > 20100)
                throw new InvalidDataException("Each profile requires consented ground truth, a unique ID, and compatible ICMP measurements.");
            var sites = new HashSet<string>(StringComparer.Ordinal);
            foreach (var f in p.Features)
                if (string.IsNullOrWhiteSpace(f.SiteId) || !sites.Add(f.SiteId) || f.Samples < 2 ||
                    !double.IsFinite(f.MinimumMs) || !double.IsFinite(f.MedianMs) || !double.IsFinite(f.MadMs) ||
                    f.MinimumMs < 0 || f.MedianMs < f.MinimumMs || f.MadMs < 0)
                    throw new InvalidDataException("Invalid or duplicate fingerprint feature.");
        }
    }

    public static FingerprintAssessment Estimate(Catalog catalog, MeasurementSession session, FingerprintDatabase? database,
        uint? asn = null, string accessTechnology = "unknown", AccessTopology? topology = null)
    {
        if (database is null || database.Profiles.Count == 0)
            return new("no-trained-data", [], "No empirical profiles were supplied. Geographic candidates remain uncalibrated heuristics.");
        var current = Extract(catalog, session);
        if (current.Count < 4) return new("insufficient-overlap", [], "At least four independent sites with repeated compatible timing samples are required.");
        var observedRouters = (topology?.SharedRouters ?? []).Select(r => r.Address).ToHashSet(StringComparer.Ordinal);
        var matches = new List<FingerprintMatch>();
        foreach (var profile in database.Profiles.Where(p => p.AddressFamily == session.AddressFamily && p.GroundTruthConsented &&
            p.Protocol == "icmp" && p.TimingMethod == "elapsed-upper-v1" &&
            p.CapturedUtc <= DateTimeOffset.UtcNow.AddMinutes(5) && p.CapturedUtc >= DateTimeOffset.UtcNow.AddDays(-180)))
        {
            var pairs = profile.Features.Where(f => current.ContainsKey(f.SiteId)).Select(f => (Reference: f, Current: current[f.SiteId])).ToArray();
            if (pairs.Length < 4) continue;
            // Both baselines use exactly the same intersection: absent dimensions must not change the baseline.
            double baselineReference = pairs.Min(p => p.Reference.MinimumMs), baselineCurrent = pairs.Min(p => p.Current.MinimumMs);
            double loss = 0;
            foreach (var pair in pairs)
            {
                double noise = Math.Max(.2, 1.4826 * (pair.Reference.MadMs + pair.Current.MadMs));
                double delta = ((pair.Current.MinimumMs - baselineCurrent) - (pair.Reference.MinimumMs - baselineReference)) / noise;
                double z = Math.Abs(delta);
                loss += z <= 2 ? .5 * z * z : 2 * (z - 1);
            }
            loss /= pairs.Length;
            int comparisons = 0, inversions = 0;
            for (int i = 0; i < Math.Min(32, pairs.Length); i++) for (int j = i + 1; j < Math.Min(32, pairs.Length); j++)
            {
                double observed = pairs[i].Current.MinimumMs - pairs[j].Current.MinimumMs;
                double reference = pairs[i].Reference.MinimumMs - pairs[j].Reference.MinimumMs;
                double noise = Math.Max(.2, pairs[i].Current.MadMs + pairs[j].Current.MadMs + pairs[i].Reference.MadMs + pairs[j].Reference.MadMs);
                if (Math.Abs(observed) <= noise || Math.Abs(reference) <= noise) continue;
                comparisons++; if (Math.Sign(observed) != Math.Sign(reference)) inversions++;
            }
            if (comparisons > 0) loss += 2.0 * inversions / comparisons;
            // Operator/access and topology are bounded soft hints, not a substitute for RTT agreement.
            bool sameAsn = asn.HasValue && profile.Asn == asn;
            if (asn.HasValue && profile.Asn.HasValue && !sameAsn) loss += .75;
            if (accessTechnology != "unknown" && profile.AccessTechnology != "unknown" && accessTechnology != profile.AccessTechnology) loss += .4;
            var referenceRouters = profile.AccessRouters.ToHashSet(StringComparer.Ordinal);
            if (referenceRouters.Count > 0 && observedRouters.Count > 0)
                loss += .25 * (1 - (double)referenceRouters.Intersect(observedRouters).Count() / referenceRouters.Union(observedRouters).Count());
            loss += 1.0 / Math.Sqrt(pairs.Length);
            matches.Add(new(profile.Id, profile.Position, profile.CountryCode, profile.Region, profile.Locality,
                0, loss, pairs.Length, sameAsn, Math.Max(5, profile.GroundTruthUncertaintyKm)));
        }
        // Repeated observations from a household/group must not multiply that location's weight.
        var groups = database.Profiles.ToDictionary(p => p.Id, p => p.DatasetGroup ?? p.Id, StringComparer.Ordinal);
        var selected = matches.OrderBy(m => m.Distance).DistinctBy(m => groups[m.ProfileId]).Take(12).ToArray();
        if (selected.Length == 0) return new("insufficient-overlap", [], "No recent compatible profile overlaps at four independent sites.");
        double best = selected[0].Distance;
        var weights = selected.Select(m => Math.Exp(-Math.Min(50, (m.Distance - best) / 2))).ToArray();
        double sum = weights.Sum();
        return new("relative-profile-matches", selected.Select((m, i) => m with { RelativeScore = weights[i] / sum }).ToArray(),
            "Relative RTT/ranking similarity; not calibrated probabilities. Coverage gaps, VPN exits and operator changes can cause wrong matches.");
    }

    public static NetworkFingerprint Capture(string id, Catalog catalog, MeasurementSession session, GeoPoint knownPosition,
        string country, string region, string locality, uint? asn, bool groundTruthConsented,
        double uncertaintyKm = 10, string accessTechnology = "unknown", string? datasetGroup = null)
    {
        if (!groundTruthConsented) throw new InvalidOperationException("Ground truth must be explicitly provided with consent; predicted positions are not training labels.");
        knownPosition.Validate();
        var profile = new NetworkFingerprint(id, knownPosition, country, region, locality, asn, session.AddressFamily, "icmp",
            DateTimeOffset.UtcNow, Extract(catalog, session).Values.ToList())
        {
            GroundTruthConsented = true, GroundTruthUncertaintyKm = uncertaintyKm,
            AccessTechnology = accessTechnology, DatasetGroup = datasetGroup,
            AccessRouters = AccessTopologyAnalyzer.Analyze(session).SharedRouters.Select(r => r.Address).ToArray()
        };
        Validate(new() { Profiles = [profile] });
        return profile;
    }
}
